"use client";

import {
  Children,
  isValidElement,
  useEffect,
  useRef,
  useState,
  type ComponentPropsWithoutRef,
  type MouseEventHandler,
  type ReactNode,
} from "react";
import {
  AnimatePresence,
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
  type HTMLMotionProps,
} from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export type AnimatedListReplay = "never" | "both" | "up" | "down";
export type AnimatedListItemVariant = "filled" | "bordered" | "transparent";
export type AnimatedListDescriptionPlacement = "below" | "inline";
export type AnimatedListSwipeActionTone = "neutral" | "success" | "warning" | "danger";

export interface AnimatedListSwipeAction {
  /** Visible action label. It can contain custom React content. */
  label: ReactNode;
  /** Runs only after the revealed action is pressed. */
  onAction: () => void;
  /** Optional icon displayed above or beside the label, depending on available space. */
  icon?: ReactNode;
  /** Accessible name when the visible label is not descriptive. */
  ariaLabel?: string;
  /** Semantic color treatment for the action surface. */
  tone?: AnimatedListSwipeActionTone;
  /** Additional styling hook for one action. */
  className?: string;
}

export interface AnimatedListProps<Item>
  extends Omit<HTMLMotionProps<"ul">, "children"> {
  /** Data used with renderItem. */
  items?: readonly Item[];
  /** Direct item content. Each child is wrapped in a semantic list item. */
  children?: ReactNode;
  /** Renders an item when items is supplied. */
  renderItem?: (item: Item, index: number) => ReactNode;
  /** Returns a stable key for data items. */
  getItemKey?: (item: Item, index: number) => string | number;
  /** Whether entries play once or replay while scrolling. */
  replay?: AnimatedListReplay;
  /** Portion of an entry that must enter the viewport before it reveals. */
  amount?: number;
  /** Delay between each item, in seconds. */
  stagger?: number;
  /** Reduces spacing and item padding for compact collections. */
  dense?: boolean;
  /** Accessible label for the list. */
  "aria-label"?: string;
}

export interface AnimatedListItemProps
  extends Omit<ComponentPropsWithoutRef<"div">, "title"> {
  variant?: AnimatedListItemVariant;
  leading?: ReactNode;
  title?: ReactNode;
  description?: ReactNode;
  /** Places the supporting text below the title or inline beside it. */
  descriptionPlacement?: AnimatedListDescriptionPlacement;
  trailing?: ReactNode;
  href?: string;
  disabled?: boolean;
  onClick?: MouseEventHandler<HTMLElement>;
  /** One optional action on each horizontal swipe direction. */
  swipeActions?: {
    left?: AnimatedListSwipeAction;
    right?: AnimatedListSwipeAction;
  };
}

type ScrollDirection = "up" | "down";

function useScrollDirection() {
  const direction = useRef<ScrollDirection>("down");

  useEffect(() => {
    const positions = new WeakMap<object, number>();

    const getScrollTop = (target: EventTarget | null) => {
      if (target instanceof Element) return target.scrollTop;
      return document.scrollingElement?.scrollTop ?? window.scrollY;
    };

    const updateDirection = (event: Event) => {
      const target = event.target && typeof event.target === "object"
        ? event.target
        : document;
      const nextScrollTop = getScrollTop(event.target);
      const previousScrollTop = positions.get(target) ?? nextScrollTop;

      if (nextScrollTop !== previousScrollTop) {
        direction.current = nextScrollTop > previousScrollTop ? "down" : "up";
      }
      positions.set(target, nextScrollTop);
    };

    const updateWheelDirection = (event: WheelEvent) => {
      if (event.deltaY !== 0) {
        direction.current = event.deltaY > 0 ? "down" : "up";
      }
    };

    document.addEventListener("scroll", updateDirection, { capture: true, passive: true });
    document.addEventListener("wheel", updateWheelDirection, { capture: true, passive: true });
    return () => {
      document.removeEventListener("scroll", updateDirection, true);
      document.removeEventListener("wheel", updateWheelDirection, true);
    };
  }, []);

  return direction;
}

function shouldReplay(replay: AnimatedListReplay, direction: ScrollDirection) {
  return replay === "both" || replay === direction;
}

function AnimatedListEntry({
  children,
  index,
  replay,
  amount,
  stagger,
  getScrollDirection,
}: {
  children: ReactNode;
  index: number;
  replay: AnimatedListReplay;
  amount: number;
  stagger: number;
  getScrollDirection: () => ScrollDirection;
}) {
  const ref = useRef<HTMLLIElement>(null);
  const reduceMotion = useReducedMotion() ?? false;
  const [entryDirection, setEntryDirection] = useState<ScrollDirection>("down");
  const [revealed, setRevealed] = useState(false);
  const [canAnimate, setCanAnimate] = useState(false);

  const hiddenTransform = entryDirection === "up"
    ? "translateY(-25%) scale(0.97)"
    : "translateY(25%) scale(0.97)";
  const delay = replay === "never" ? index * stagger : 0;
  return (
    <motion.li
      ref={ref}
      className="relative z-[1] w-full min-w-0 list-none will-change-[transform,opacity,filter] motion-reduce:will-change-auto"
      layout={!reduceMotion}
      initial={reduceMotion ? false : {
        opacity: 0,
        transform: hiddenTransform,
        filter: `blur(${motionTokens.blur.subtle}px)`,
      }}
      viewport={{ amount, once: replay === "never" }}
      onViewportEnter={() => {
        const direction = getScrollDirection();
        setEntryDirection(direction);
        setCanAnimate(replay === "never" || shouldReplay(replay, direction));
        setRevealed(true);
      }}
      onViewportLeave={() => {
        if (replay !== "never") {
          setCanAnimate(false);
          setRevealed(false);
        }
      }}
      animate={
        reduceMotion || revealed
          ? { opacity: 1, transform: "translateY(0%) scale(1)", filter: "blur(0px)" }
          : { opacity: 0, transform: hiddenTransform, filter: `blur(${motionTokens.blur.subtle}px)` }
      }
      exit={reduceMotion ? { opacity: 0 } : {
        opacity: 0,
        transform: hiddenTransform,
        filter: `blur(${motionTokens.blur.subtle}px)`,
      }}
      transition={
        reduceMotion
          ? { duration: motionTokens.duration.fast }
          : revealed && canAnimate
            ? {
              opacity: {
                duration: motionTokens.duration.considered,
                ease: motionTokens.ease.enter,
                delay,
              },
              transform: {
                duration: motionTokens.duration.reveal,
                ease: motionTokens.ease.enter,
                delay,
              },
              filter: {
                duration: motionTokens.duration.considered,
                ease: motionTokens.ease.enter,
                delay,
              },
              layout: {
                duration: motionTokens.duration.standard,
                ease: motionTokens.ease.standard,
              },
            }
            : revealed
              ? { duration: 0 }
              : { duration: 0.18, ease: motionTokens.ease.enter }
      }
    >
      {children}
    </motion.li>
  );
}

export function AnimatedList<Item>({
  items,
  children,
  renderItem,
  getItemKey,
  replay = "never",
  amount = 0.25,
  stagger = motionTokens.stagger.item,
  dense = false,
  className,
  onPointerMove,
  onPointerLeave,
  ...props
}: AnimatedListProps<Item>) {
  const scrollDirection = useScrollDirection();
  const reduceMotion = useReducedMotion() ?? false;
  const listRef = useRef<HTMLUListElement>(null);
  const hoverTarget = useRef<HTMLElement | null>(null);
  const hoverX = useMotionValue(0);
  const hoverY = useMotionValue(0);
  const hoverWidth = useMotionValue(0);
  const hoverHeight = useMotionValue(0);
  const hoverOpacity = useMotionValue(0);
  const content = items
    ? items.map((item, index) => ({
        key: getItemKey?.(item, index) ?? index,
        node: renderItem?.(item, index),
      }))
    : Children.toArray(children).map((node, index) => ({
        key: isValidElement(node) && node.key !== null ? node.key : index,
        node,
      }));
  const safeAmount = Math.min(1, Math.max(0, amount));
  const safeStagger = Math.max(0, stagger);

  const moveHover = (item: HTMLElement) => {
    if (hoverTarget.current === item) return;
    const list = listRef.current;
    if (!list) return;

    const listBounds = list.getBoundingClientRect();
    const itemBounds = item.getBoundingClientRect();
    const target = {
      x: itemBounds.left - listBounds.left + list.scrollLeft,
      y: itemBounds.top - listBounds.top + list.scrollTop,
      width: itemBounds.width,
      height: itemBounds.height,
    };

    if (!hoverTarget.current || reduceMotion) {
      hoverX.jump(target.x);
      hoverY.jump(target.y);
      hoverWidth.jump(target.width);
      hoverHeight.jump(target.height);
    } else {
      animate(hoverX, target.x, motionTokens.spring.smooth);
      animate(hoverY, target.y, motionTokens.spring.smooth);
      animate(hoverWidth, target.width, motionTokens.spring.smooth);
      animate(hoverHeight, target.height, motionTokens.spring.smooth);
    }

    hoverTarget.current = item;
    hoverOpacity.set(1);
  };

  const hideHover = () => {
    hoverTarget.current = null;
    animate(hoverOpacity, 0, reduceMotion
      ? { duration: 0 }
      : { duration: motionTokens.duration.fast, ease: motionTokens.ease.standard });
  };

  return (
    <motion.ul
      {...props}
      ref={listRef}
      className={["relative m-0 grid w-full min-w-0 list-none gap-2.5 p-0 data-[dense]:gap-1.5 data-[dense]:[&_.sya-list-item]:min-h-12 data-[dense]:[&_.sya-list-item]:gap-2 data-[dense]:[&_.sya-list-item]:px-2.5 data-[dense]:[&_.sya-list-item]:py-2 data-[dense]:[&_.sya-list-copy]:gap-px", className].filter(Boolean).join(" ")}
      data-dense={dense || undefined}
      onPointerMove={(event) => {
        const item = (event.target as HTMLElement).closest<HTMLElement>("[data-animated-list-item]");
        if (item) moveHover(item);
        onPointerMove?.(event);
      }}
      onPointerLeave={(event) => {
        hideHover();
        onPointerLeave?.(event);
      }}
    >
      <motion.span
        className="pointer-events-none absolute z-[2] rounded-[var(--radius-surface)] bg-[color-mix(in_srgb,var(--surface-muted)_24%,transparent)] shadow-[inset_0_0_0_1px_color-mix(in_srgb,var(--focus)_22%,transparent)]"
        style={{ x: hoverX, y: hoverY, width: hoverWidth, height: hoverHeight, opacity: hoverOpacity }}
        aria-hidden="true"
      />
      <AnimatePresence initial={false} mode="popLayout">
        {content.map(({ key, node }, index) => (
          <AnimatedListEntry
            key={key}
            index={index}
            replay={replay}
            amount={safeAmount}
            stagger={safeStagger}
            getScrollDirection={() => scrollDirection.current}
          >
            {node}
          </AnimatedListEntry>
        ))}
      </AnimatePresence>
    </motion.ul>
  );
}

function SwipeableListItem({
  children,
  actions,
  disabled,
}: {
  children: ReactNode;
  actions: NonNullable<AnimatedListItemProps["swipeActions"]>;
  disabled: boolean;
}) {
  const reduceMotion = useReducedMotion() ?? false;
  const leftWidth = actions.left ? 104 : 0;
  const rightWidth = actions.right ? 104 : 0;
  const x = useMotionValue(-leftWidth);
  const [openSide, setOpenSide] = useState<"left" | "right" | null>(null);
  const leftActionRef = useRef<HTMLButtonElement>(null);
  const rightActionRef = useRef<HTMLButtonElement>(null);

  const settle = (side: "left" | "right" | null, velocity = 0) => {
    const target = side === "left"
      ? 0
      : side === "right"
        ? -(leftWidth + rightWidth)
        : -leftWidth;
    setOpenSide(side);

    if (reduceMotion) {
      x.jump(target);
      return;
    }

    animate(x, target, { ...motionTokens.spring.smooth, velocity });
  };

  const revealForKeyboard = (side: "left" | "right") => {
    if (!actions[side] || disabled) return;
    settle(side);
    requestAnimationFrame(() => {
      (side === "left" ? leftActionRef : rightActionRef).current?.focus();
    });
  };

  const actionClassName = (side: "left" | "right", action: AnimatedListSwipeAction) => [
    "sya-swipe-action inline-flex w-[104px] items-center justify-center gap-1.5 border-0 text-center text-xs leading-[1.2] font-bold transition-[border-radius] duration-[var(--duration-standard)] ease-[var(--ease-standard)] focus-visible:relative focus-visible:z-[1] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-[-4px]",
    side === "left" ? "col-[1] bg-[var(--primary)] text-[var(--primary-foreground)]" : "col-[3] bg-[var(--primary)] text-[var(--primary-foreground)]",
    action.tone === "success" && "bg-[var(--success)] text-[var(--success-foreground)]",
    action.tone === "warning" && "bg-[var(--warning)] text-[var(--warning-foreground)]",
    action.tone === "danger" && "bg-[var(--danger)] text-[var(--danger-foreground)]",
    action.className,
  ].filter(Boolean).join(" ");

  return (
    <div
      className={[
        "relative overflow-hidden rounded-[var(--radius-surface)] touch-pan-y",
        openSide === "left" && "[&_.sya-swipe-left]:rounded-l-[var(--radius-surface)] [&_.sya-swipe-content_>:first-child]:rounded-tl-none [&_.sya-swipe-content_>:first-child]:rounded-bl-none",
        openSide === "right" && "[&_.sya-swipe-right]:rounded-r-[var(--radius-surface)] [&_.sya-swipe-content_>:first-child]:rounded-tr-none [&_.sya-swipe-content_>:first-child]:rounded-br-none",
      ].filter(Boolean).join(" ")}
      style={{
        "--swipe-left-width": `${leftWidth}px`,
        "--swipe-right-width": `${rightWidth}px`,
      } as React.CSSProperties}
    >
      <motion.div
        className="grid w-[calc(100%+var(--swipe-left-width)+var(--swipe-right-width))] grid-cols-[var(--swipe-left-width)_minmax(0,1fr)_var(--swipe-right-width)] items-stretch touch-pan-y will-change-transform motion-reduce:will-change-auto"
        drag={disabled || reduceMotion ? false : "x"}
        dragDirectionLock
        dragConstraints={{ left: -(leftWidth + rightWidth), right: 0 }}
        dragElastic={0.12}
        style={{ x }}
        onDragStart={() => setOpenSide(null)}
        onDragEnd={(_, info) => {
          const projectedOffset = x.get() + info.velocity.x * 0.12 + leftWidth;
          if (actions.left && projectedOffset > leftWidth * 0.42) {
            settle("left", info.velocity.x);
          } else if (actions.right && projectedOffset < -rightWidth * 0.42) {
            settle("right", info.velocity.x);
          } else {
            settle(null, info.velocity.x);
          }
        }}
        onKeyDownCapture={(event) => {
          if (!event.altKey) return;
          if (event.key === "ArrowRight") {
            event.preventDefault();
            revealForKeyboard("left");
          }
          if (event.key === "ArrowLeft") {
            event.preventDefault();
            revealForKeyboard("right");
          }
        }}
        onPointerDown={(event) => {
          const target = event.target as HTMLElement;
          if (openSide && !target.closest("button")) settle(null);
        }}
      >
        {actions.left ? (
          <button
            ref={leftActionRef}
            type="button"
            className={["sya-swipe-left", actionClassName("left", actions.left)].join(" ")}
            tabIndex={openSide === "left" ? 0 : -1}
            aria-hidden={openSide !== "left" || undefined}
            aria-label={actions.left.ariaLabel}
            disabled={disabled}
            onClick={() => {
              actions.left?.onAction();
              settle(null);
            }}
          >
            {actions.left.icon ? <span className="grid place-items-center">{actions.left.icon}</span> : null}
            <span>{actions.left.label}</span>
          </button>
        ) : null}
        <div className="sya-swipe-content col-[2] touch-pan-y [&_>:first-child]:transition-[border-radius] [&_>:first-child]:duration-[var(--duration-standard)] [&_>:first-child]:ease-[var(--ease-standard)]">{children}</div>
        {actions.right ? (
          <button
            ref={rightActionRef}
            type="button"
            className={["sya-swipe-right", actionClassName("right", actions.right)].join(" ")}
            tabIndex={openSide === "right" ? 0 : -1}
            aria-hidden={openSide !== "right" || undefined}
            aria-label={actions.right.ariaLabel}
            disabled={disabled}
            onClick={() => {
              actions.right?.onAction();
              settle(null);
            }}
          >
            {actions.right.icon ? <span className="grid place-items-center">{actions.right.icon}</span> : null}
            <span>{actions.right.label}</span>
          </button>
        ) : null}
      </motion.div>
    </div>
  );
}

export function AnimatedListItem({
  variant = "bordered",
  leading,
  title,
  description,
  descriptionPlacement = "below",
  trailing,
  href,
  disabled = false,
  onClick,
  swipeActions,
  children,
  className,
  ...props
}: AnimatedListItemProps) {
  const content = children ?? (
    <>
      {leading ? <span className="grid shrink-0 place-items-center text-[var(--text-secondary)]">{leading}</span> : null}
      {title || description ? (
        <span className={descriptionPlacement === "inline" ? "flex min-w-0 items-baseline gap-0 [&_.sya-list-title]:min-w-0 [&_.sya-list-description]:min-w-0 [&_.sya-list-description]:before:mr-2 [&_.sya-list-description]:before:text-[var(--border)] [&_.sya-list-description]:before:content-['·']" : "sya-list-copy grid min-w-0 gap-[3px]"}>
          {title ? <span className="sya-list-title overflow-hidden text-sm font-[650] text-ellipsis whitespace-nowrap">{title}</span> : null}
          {description ? <span className="sya-list-description overflow-hidden text-xs leading-[1.45] text-ellipsis whitespace-nowrap text-[var(--text-secondary)]">{description}</span> : null}
        </span>
      ) : null}
      {trailing ? <span className="ml-auto grid shrink-0 place-items-center text-[var(--text-secondary)]">{trailing}</span> : null}
    </>
  );
  const contentClassName = [
    "sya-list-item flex min-h-16 w-full min-w-0 items-center gap-3 rounded-[var(--radius-surface)] border px-3.5 py-3 text-left no-underline text-[var(--text)]",
    variant === "filled" && "border-transparent bg-[var(--surface-muted)]",
    variant === "bordered" && "border-[var(--border)] bg-[var(--surface)]",
    variant === "transparent" && "border-transparent bg-transparent",
    (href || onClick) && "cursor-pointer transition-[border-color,background-color,color] duration-[var(--duration-fast)] ease-[var(--ease-standard)] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-3 disabled:cursor-not-allowed disabled:opacity-[0.48] aria-disabled:cursor-not-allowed aria-disabled:opacity-[0.48] motion-reduce:transition-[border-color,background-color,color]",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  let item: ReactNode;

  if (href) {
    const anchorProps = props as Omit<ComponentPropsWithoutRef<"a">, "children" | "className" | "href" | "onClick">;

    item = (
      <a
        {...anchorProps}
        data-animated-list-item=""
        href={disabled ? undefined : href}
        className={contentClassName}
        aria-disabled={disabled || undefined}
        onClick={(event) => {
          if (disabled) event.preventDefault();
          onClick?.(event);
        }}
      >
        {content}
      </a>
    );
  } else if (onClick) {
    const buttonProps = props as Omit<ComponentPropsWithoutRef<"button">, "children" | "className" | "disabled" | "onClick" | "type">;

    item = (
      <button
        {...buttonProps}
        data-animated-list-item=""
        type="button"
        className={contentClassName}
        disabled={disabled}
        onClick={onClick}
      >
        {content}
      </button>
    );
  } else {
    item = <div {...props} data-animated-list-item="" className={contentClassName}>{content}</div>;
  }

  return swipeActions?.left || swipeActions?.right
    ? <SwipeableListItem actions={swipeActions} disabled={disabled}>{item}</SwipeableListItem>
    : item;
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  Fragment,
  type CSSProperties,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { animate, motion, useMotionValue, useReducedMotion } from "motion/react";
import { Search } from "lucide-react";
import {
  AnimatedList,
  AnimatedListItem,
  type AnimatedListItemProps,
  type AnimatedListItemVariant,
  type AnimatedListProps,
} from "../animated-list/animated-list";
import { Button } from "../button/button";
import { Input, type InputProps } from "../input/input";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export type ExpandingSearchTrigger = "icon" | "icon-text" | "field";
export type ExpandingSearchAnchor = "start" | "center" | "end" | number;
export type ExpandingSearchPanelSize = "small" | "medium" | "large" | "xl";

export interface ExpandingSearchItem {
  value: string;
  label: ReactNode;
  description?: ReactNode;
  icon?: ReactNode;
  keywords?: string[];
  /** Optional result section label. Generated results with the same label stay together. */
  group?: string;
  disabled?: boolean;
}

export interface ExpandingSearchChildrenContext {
  query: string;
  close: () => void;
}

/** Options forwarded to the generated AnimatedList result wrapper. */
export type ExpandingSearchAnimatedListProps = Omit<
  AnimatedListProps<ExpandingSearchItem>,
  "children" | "items" | "renderItem" | "getItemKey" | "id" | "className" | "aria-label"
>;

/** Options forwarded to each generated AnimatedListItem result row. */
export type ExpandingSearchItemProps = Pick<
  AnimatedListItemProps,
  "variant" | "descriptionPlacement" | "trailing" | "href" | "swipeActions"
>;

export type ExpandingSearchItemPropsResolver = (
  item: ExpandingSearchItem,
  context: { query: string; select: () => void },
) => ExpandingSearchItemProps;

export interface ExpandingSearchProps extends Omit<
  InputProps,
  "children" | "label" | "hint" | "error" | "prefixIcon" | "suffixIcon" | "suffixControl" | "value" | "defaultValue" | "onValueChange" | "type" | "expanded" | "expandedContent"
> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  trigger?: ExpandingSearchTrigger;
  triggerLabel?: ReactNode;
  triggerAriaLabel?: string;
  anchor?: ExpandingSearchAnchor;
  panelSize?: ExpandingSearchPanelSize;
  /** Dims and lightly blurs the page behind an open search surface. */
  backdrop?: boolean;
  expandedWidth?: number;
  fieldWidth?: number;
  items?: ExpandingSearchItem[];
  defaultItems?: ExpandingSearchItem[];
  /** Direct result content. It takes precedence over items and stays animated by AnimatedList. */
  children?: ReactNode | ((context: ExpandingSearchChildrenContext) => ReactNode);
  /** Uses Animated List for result entry motion and hover treatment. */
  animatedList?: boolean;
  /** Options forwarded to AnimatedList while animatedList is enabled. */
  animatedListProps?: ExpandingSearchAnimatedListProps;
  /** Reduces padding and gaps between generated or custom result rows. */
  listDense?: boolean;
  /** Visual treatment for generated items when items or defaultItems are used. */
  itemVariant?: AnimatedListItemVariant;
  /** Item options, or a resolver for item-specific options such as inline metadata and swipe actions. */
  itemProps?: ExpandingSearchItemProps | ExpandingSearchItemPropsResolver;
  emptyState?: ReactNode;
  resultsLabel?: string;
  filterItems?: (items: ExpandingSearchItem[], query: string) => ExpandingSearchItem[];
  renderItem?: (item: ExpandingSearchItem, context: { query: string; select: () => void }) => ReactNode;
  onItemSelect?: (item: ExpandingSearchItem) => void;
}

function resolveAnchor(anchor: ExpandingSearchAnchor) {
  if (anchor === "start") return { position: "0%", shift: "0%" };
  if (anchor === "end") return { position: "100%", shift: "-100%" };
  const percentage = typeof anchor === "number" ? Math.min(100, Math.max(0, anchor)) : 50;
  return { position: `${percentage}%`, shift: `-${percentage}%` };
}

function defaultSearch(items: ExpandingSearchItem[], query: string) {
  const normalizedQuery = query.trim().toLocaleLowerCase();
  if (!normalizedQuery) return items;

  return items.filter((item) => {
    const label = typeof item.label === "string" ? item.label : "";
    return [item.value, label, ...(item.keywords ?? [])]
      .join(" ")
      .toLocaleLowerCase()
      .includes(normalizedQuery);
  });
}

function subscribeToPortal() {
  return () => {};
}

export function ExpandingSearch({
  value,
  defaultValue = "",
  onValueChange,
  open,
  defaultOpen = false,
  onOpenChange,
  trigger = "icon",
  triggerLabel = "Search",
  triggerAriaLabel = "Open search",
  anchor = "center",
  panelSize = "medium",
  backdrop = false,
  expandedWidth,
  fieldWidth = 360,
  items,
  defaultItems,
  children,
  animatedList = true,
  animatedListProps,
  listDense = true,
  itemVariant = "transparent",
  itemProps,
  emptyState = "No results yet.",
  resultsLabel = "Search results",
  filterItems = defaultSearch,
  renderItem,
  onItemSelect,
  variant = "filled",
  disabled,
  placeholder = "Search",
  onKeyDown,
  className,
  ...inputProps
}: ExpandingSearchProps) {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const [searchContentVisible, setSearchContentVisible] = useState(defaultOpen);
  const [measuredClosedWidth, setMeasuredClosedWidth] = useState(52);
  const [portalPosition, setPortalPosition] = useState<{ left: number; top: number } | null>(null);
  const portalContainer = useSyncExternalStore(
    subscribeToPortal,
    () => document.body,
    () => null,
  );
  const rootRef = useRef<HTMLDivElement>(null);
  const surfaceRef = useRef<HTMLDivElement>(null);
  const resultPanelRef = useRef<HTMLDivElement>(null);
  const sizerRef = useRef<HTMLSpanElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const expandedRef = useRef(false);
  const resultsId = useId();
  const reduceMotion = useReducedMotion() ?? false;
  const query = value ?? internalValue;
  const expanded = open ?? internalOpen;
  const sourceItems = useMemo(() => items ?? defaultItems ?? [], [defaultItems, items]);
  const results = useMemo(
    () => filterItems(sourceItems, query),
    [filterItems, query, sourceItems],
  );

  useLayoutEffect(() => {
    const list = resultPanelRef.current?.querySelector<HTMLElement>("[data-expanding-search-results]");
    if (!list) return;
    list.scrollTop = 0;
    list.scrollLeft = 0;
  }, [query, results.length]);
  const hasCustomContent = children !== undefined;
  const resultGroups = useMemo(() => {
    const groups = new Map<string, ExpandingSearchItem[]>();

    for (const item of results) {
      const label = item.group ?? "";
      const groupItems = groups.get(label) ?? [];
      groupItems.push(item);
      groups.set(label, groupItems);
    }

    return Array.from(groups, ([label, items]) => ({ label, items }));
  }, [results]);
  const hasResultGroups = resultGroups.some((group) => group.label);
  const anchorStyle = resolveAnchor(anchor);
  const closedWidth = trigger === "field" ? fieldWidth : measuredClosedWidth;
  const defaultExpandedWidth = panelSize === "small"
    ? 360
    : panelSize === "large"
      ? 600
      : panelSize === "xl"
        ? 720
        : 480;
  const openWidth = Math.max(expandedWidth ?? defaultExpandedWidth, closedWidth);
  const surfaceWidth = useMotionValue(closedWidth);
  const shouldPortalSurface = backdrop && Boolean(portalContainer) && Boolean(portalPosition);

  const updatePortalPosition = useCallback(() => {
    const rect = rootRef.current?.getBoundingClientRect();
    if (!rect) return;
    const anchorRatio = Number.parseFloat(anchorStyle.position) / 100;
    setPortalPosition({ left: rect.left + rect.width * anchorRatio, top: rect.top });
  }, [anchorStyle.position]);

  const setExpanded = useCallback((nextOpen: boolean) => {
    if (open === undefined) setInternalOpen(nextOpen);
    onOpenChange?.(nextOpen);
  }, [onOpenChange, open]);

  const openSearch = useCallback(() => {
    updatePortalPosition();
    setSearchContentVisible(true);
    setExpanded(true);
  }, [setExpanded, updatePortalPosition]);

  useEffect(() => {
    if (!expanded || searchContentVisible) return;
    const frame = requestAnimationFrame(() => setSearchContentVisible(true));
    return () => cancelAnimationFrame(frame);
  }, [expanded, searchContentVisible]);

  useLayoutEffect(() => {
    expandedRef.current = expanded;
    const targetWidth = expanded ? openWidth : closedWidth;

    if (reduceMotion) {
      surfaceWidth.jump(targetWidth);
      if (!expanded) {
        const frame = requestAnimationFrame(() => {
          if (!expandedRef.current) setSearchContentVisible(false);
        });
        return () => cancelAnimationFrame(frame);
      }
      return;
    }

    const control = animate(
      surfaceWidth,
      targetWidth,
      expanded ? motionTokens.spring.morph : motionTokens.spring.smooth,
    );

    if (!expanded) {
      void control.then(() => {
        if (!expandedRef.current) setSearchContentVisible(false);
      });
    }

    return () => control.stop();
  }, [closedWidth, expanded, openWidth, reduceMotion, surfaceWidth]);

  useLayoutEffect(() => {
    if (trigger === "field") return;

    const sizer = sizerRef.current;
    if (!sizer) return;
    const observer = new ResizeObserver(() => {
      setMeasuredClosedWidth(Math.ceil(sizer.offsetWidth));
    });
    observer.observe(sizer);
    return () => observer.disconnect();
  }, [trigger, triggerLabel]);

  useEffect(() => {
    if (!expanded || !searchContentVisible) return;
    requestAnimationFrame(() => inputRef.current?.focus({ preventScroll: true }));

    const handleOutsidePress = (event: PointerEvent) => {
      const target = event.target as Node;
      if (!rootRef.current?.contains(target) && !surfaceRef.current?.contains(target)) setExpanded(false);
    };
    document.addEventListener("pointerdown", handleOutsidePress);
    return () => document.removeEventListener("pointerdown", handleOutsidePress);
  }, [expanded, searchContentVisible, setExpanded]);

  useLayoutEffect(() => {
    if (!shouldPortalSurface) return;

    updatePortalPosition();
    window.addEventListener("resize", updatePortalPosition);
    window.addEventListener("scroll", updatePortalPosition, true);
    return () => {
      window.removeEventListener("resize", updatePortalPosition);
      window.removeEventListener("scroll", updatePortalPosition, true);
    };
  }, [expanded, searchContentVisible, shouldPortalSurface, updatePortalPosition]);

  const setQuery = (nextValue: string) => {
    if (value === undefined) setInternalValue(nextValue);
    onValueChange?.(nextValue);
  };

  const selectItem = (item: ExpandingSearchItem) => {
    if (item.disabled) return;
    onItemSelect?.(item);
    setExpanded(false);
  };
  const customContent = typeof children === "function"
    ? children({ query, close: () => setExpanded(false) })
    : children;
  const getGeneratedItemProps = (item: ExpandingSearchItem) => {
    const context = { query, select: () => selectItem(item) };
    const resolved = typeof itemProps === "function" ? itemProps(item, context) : itemProps;
    return { variant: itemVariant, ...resolved };
  };

  const renderGeneratedItem = (item: ExpandingSearchItem) => {
    const resolvedItemProps = getGeneratedItemProps(item);

    return (
      <AnimatedListItem
        className="w-full rounded-xl"
        {...resolvedItemProps}
        leading={item.icon ? <span className="grid shrink-0 place-items-center text-[var(--text-secondary)] [&>svg]:size-[17px]" aria-hidden="true">{item.icon}</span> : undefined}
        title={item.label}
        description={item.description}
        disabled={item.disabled}
        onClick={() => selectItem(item)}
      />
    );
  };
  const renderResult = (item: ExpandingSearchItem) => renderItem ? (
    <span className="block">
      {renderItem(item, { query, select: () => selectItem(item) })}
    </span>
  ) : renderGeneratedItem(item);
  const renderResults = (staticList = false) => {
    if (!hasResultGroups) return results.map((item) => (
      staticList
        ? <li key={item.value} className="w-full min-w-0">{renderResult(item)}</li>
        : <Fragment key={item.value}>{renderResult(item)}</Fragment>
    ));

    return resultGroups.flatMap((group) => {
      const rows = group.items.map((item) => (
        staticList
          ? <li key={item.value} className="w-full min-w-0">{renderResult(item)}</li>
          : <Fragment key={item.value}>{renderResult(item)}</Fragment>
      ));
      if (!group.label) return rows;

      const heading = staticList ? (
        <li key={`${group.label}-heading`} className="min-w-0 list-none">
          <p className="mx-2.5 mt-1 mb-0.5 text-[11px] leading-[1.3] font-[750] tracking-[0.08em] uppercase text-[var(--text-secondary)]">{group.label}</p>
        </li>
      ) : (
        <div key={`${group.label}-heading`} className="min-w-0">
          <p className="mx-2.5 mt-1 mb-0.5 text-[11px] leading-[1.3] font-[750] tracking-[0.08em] uppercase text-[var(--text-secondary)]">{group.label}</p>
        </div>
      );

      return [heading, ...rows];
    });
  };

  const rootStyle = {
    "--expanding-search-closed-width": `${closedWidth}px`,
    "--expanding-search-anchor-position": anchorStyle.position,
    "--expanding-search-anchor-shift": anchorStyle.shift,
  } as CSSProperties;

  const isIconOnly = trigger === "icon";
  const inputSize = inputProps.dense ? "small" : inputProps.size ?? "medium";
  const controlHeightClass = {
    small: "min-h-10",
    medium: "min-h-[46px]",
    large: "min-h-[52px]",
  }[inputSize];
  const controlRootHeightClass = {
    small: "h-10",
    medium: "h-[46px]",
    large: "h-[52px]",
  }[inputSize];
  const iconWidthClass = {
    small: "w-10",
    medium: "w-[46px]",
    large: "w-[52px]",
  }[inputSize];
  const triggerContent = <><Search aria-hidden="true" />{trigger !== "icon" ? <span>{triggerLabel}</span> : null}</>;
  const resultSurfaceClass = variant === "filled"
    ? "border-transparent bg-[var(--surface-muted)]"
    : "border-[var(--border)] bg-[var(--surface)]";
  const searchTrigger = () => isIconOnly ? (
    <Button
      ref={triggerRef}
      className={["w-full justify-center rounded-[18px] !border-transparent !bg-transparent p-0 hover:!bg-transparent", controlHeightClass].join(" ")}
      variant={variant}
      tone="secondary"
      size={inputSize}
      icon={<Search />}
      aria-label={triggerAriaLabel}
      aria-expanded={false}
      aria-controls={resultsId}
      aria-hidden={expanded || undefined}
      tabIndex={expanded ? -1 : undefined}
      disabled={disabled}
      onClick={openSearch}
    />
  ) : (
    <Button
      ref={triggerRef}
      className={["w-full justify-start rounded-[18px] !border-transparent !bg-transparent !px-3.5 !text-[14px] !leading-[1.5] !font-normal !tracking-[-0.01em] hover:!bg-transparent", controlHeightClass].join(" ")}
      variant={variant}
      tone="secondary"
      size={inputSize}
      icon={<Search />}
      aria-expanded={false}
      aria-controls={resultsId}
      aria-hidden={expanded || undefined}
      tabIndex={expanded ? -1 : undefined}
      disabled={disabled}
      onClick={openSearch}
    >
      {triggerLabel}
    </Button>
  );

  const surface = (
      <motion.div
        ref={surfaceRef}
        className={[
          "absolute z-[1] top-0 left-[var(--expanding-search-anchor-position)] w-[var(--expanding-search-closed-width)] max-w-[calc(100vw-32px)] translate-x-[var(--expanding-search-anchor-shift)] origin-top rounded-[18px] border text-[var(--text)] transition-[background-color,border-color,opacity] duration-[var(--duration-fast)] ease-[var(--ease-standard)] will-change-[width] motion-reduce:duration-[0.01ms]",
          variant === "filled"
            ? "border-transparent bg-[var(--surface-muted)]"
            : "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_58%,var(--surface))]",
          expanded && "border-[var(--focus)]",
          disabled && "opacity-[0.52]",
          shouldPortalSurface && "fixed z-[111]",
        ].filter(Boolean).join(" ")}
        data-open={expanded || undefined}
        style={{
          width: surfaceWidth,
          ...(shouldPortalSurface && portalPosition ? {
            ...rootStyle,
            left: `${portalPosition.left}px`,
            top: `${portalPosition.top}px`,
          } : {}),
        }}
      >
        <>
            <motion.div
              className="relative z-[1] w-full"
              inert={trigger !== "field" && !expanded}
              aria-hidden={trigger !== "field" && !expanded}
              initial={false}
              animate={trigger === "field" || expanded
                ? { opacity: 1, filter: "blur(0px)" }
                : { opacity: 0, filter: reduceMotion ? "blur(0px)" : `blur(${motionTokens.blur.subtle}px)` }}
              transition={reduceMotion
                ? { duration: 0.1 }
                : expanded
                  ? { duration: 0.18, delay: 0.08, ease: motionTokens.ease.enter }
                  : { duration: 0.08 }}
            >
              <Input
              {...inputProps}
              ref={inputRef}
              className="w-full [&>div>div]:!border-transparent [&>div>div]:!bg-transparent"
              variant={variant}
              disabled={disabled}
              type="search"
              value={query}
              placeholder={placeholder}
              prefixIcon={<Search />}
              tabIndex={expanded || trigger === "field" ? (inputProps.tabIndex ?? 0) : -1}
              aria-expanded={expanded}
              aria-controls={resultsId}
              onFocus={(event) => {
                if (!expanded) openSearch();
                inputProps.onFocus?.(event);
              }}
              onClick={(event) => {
                if (!expanded) openSearch();
                inputProps.onClick?.(event);
              }}
              onValueChange={(nextValue) => {
                if (!expanded) openSearch();
                setQuery(nextValue);
              }}
              onKeyDown={(event) => {
                if (event.key === "Escape") {
                  event.preventDefault();
                  setExpanded(false);
                  requestAnimationFrame(() => triggerRef.current?.focus({ preventScroll: true }));
                }
                onKeyDown?.(event);
              }}
            />
            </motion.div>
            {trigger !== "field" ? (
              <motion.div
                className="absolute top-0 left-[var(--expanding-search-anchor-position)] z-[2] w-[var(--expanding-search-closed-width)] translate-x-[var(--expanding-search-anchor-shift)]"
                inert={expanded}
                initial={false}
                animate={expanded
                  ? {
                      opacity: 0,
                      scale: reduceMotion ? 1 : 0.88,
                      filter: reduceMotion ? "blur(0px)" : `blur(${motionTokens.blur.subtle}px)`,
                    }
                  : { opacity: 1, scale: 1, filter: "blur(0px)" }}
                transition={reduceMotion
                  ? { duration: 0.1 }
                  : expanded
                    ? { duration: 0.1 }
                    : { duration: 0.18, delay: 0.08, ease: motionTokens.ease.enter }}
              >
                {searchTrigger()}
              </motion.div>
            ) : null}
            {searchContentVisible ? <motion.div
              ref={resultPanelRef}
              className="absolute z-[1] top-[calc(100%+10px)] w-full min-w-0"
              initial={false}
              animate={{
                opacity: expanded ? 1 : 0,
                transform: expanded || reduceMotion
                  ? "translateY(0) scale(1)"
                  : "translateY(-3px) scale(0.985)",
              }}
              transition={reduceMotion
                ? { duration: 0.1 }
                : expanded
                  ? { duration: 0.2, delay: 0.1, ease: motionTokens.ease.enter }
                  : { duration: 0.08 }}
              style={{ transformOrigin: `${anchorStyle.position} top` }}
              aria-hidden={!expanded}
            >
            {animatedList ? (
              <AnimatedList
                id={resultsId}
                data-expanding-search-results=""
                className={[
                  "m-0 grid max-h-[300px] w-full min-w-0 overflow-x-hidden overflow-y-auto overscroll-contain rounded-[18px] border p-1.5 list-none shadow-[var(--shadow-resting)] [&>li]:w-full [&>li]:min-w-0",
                  resultSurfaceClass,
                  expanded ? "pointer-events-auto" : "pointer-events-none",
                ].filter(Boolean).join(" ")}
                aria-label={resultsLabel}
                aria-hidden={!expanded}
                {...animatedListProps}
                amount={animatedListProps?.amount ?? 0.1}
                stagger={animatedListProps?.stagger ?? 0.04}
                dense={animatedListProps?.dense ?? listDense}
              >
                {hasCustomContent ? customContent : results.length ? renderResults() : <span className="grid min-h-[104px] place-items-center p-5 text-center text-[13px] text-[var(--text-secondary)]" role="status">{emptyState}</span>}
              </AnimatedList>
            ) : (
              <ul
                id={resultsId}
                data-expanding-search-results=""
                className={[
                  "m-0 grid max-h-[300px] w-full min-w-0 gap-1.5 overflow-x-hidden overflow-y-auto overscroll-contain rounded-[18px] border p-1.5 list-none shadow-[var(--shadow-resting)] [&>li]:w-full [&>li]:min-w-0",
                  resultSurfaceClass,
                  expanded ? "pointer-events-auto" : "pointer-events-none",
                ].filter(Boolean).join(" ")}
                aria-label={resultsLabel}
                aria-hidden={!expanded}
                data-dense={listDense || undefined}
              >
                {hasCustomContent ? customContent : results.length ? renderResults(true) : <li className="grid min-h-[104px] place-items-center p-5 text-center text-[13px] text-[var(--text-secondary)]" role="status">{emptyState}</li>}
              </ul>
            )}
            </motion.div> : null}
          </>
      </motion.div>
  );

  return (
    <div
      ref={rootRef}
      className={[
        "relative z-0 inline-block w-[var(--expanding-search-closed-width)] max-w-full data-[active]:z-[120]",
        controlRootHeightClass,
        className,
      ].filter(Boolean).join(" ")}
      data-open={expanded || undefined}
      data-active={searchContentVisible || undefined}
      style={rootStyle}
    >
      <span ref={sizerRef} className={[
        "pointer-events-none absolute inline-flex box-border items-center gap-2 px-3.5 text-[14px] leading-[1.5] font-normal tracking-[-0.01em] invisible whitespace-nowrap [&>svg]:size-[18px]",
        controlHeightClass,
        trigger === "icon" && iconWidthClass,
        trigger === "icon" && "justify-center p-0",
        trigger === "field" && "w-full px-[18px]",
      ].filter(Boolean).join(" ")} aria-hidden="true">
        {triggerContent}
      </span>
      {backdrop && searchContentVisible && portalContainer ? createPortal(
        <button
          className={["pointer-events-none fixed inset-0 z-[110] border-0 bg-black/35 p-0 opacity-0 backdrop-blur-none transition-[opacity,backdrop-filter] duration-[220ms] ease-[var(--ease-standard)] motion-reduce:duration-[0.01ms]", expanded && "pointer-events-auto opacity-100 backdrop-blur-sm"].filter(Boolean).join(" ")}
          type="button"
          tabIndex={-1}
          aria-label="Close search"
          onClick={() => setExpanded(false)}
        />,
        portalContainer,
      ) : null}
      {shouldPortalSurface && portalContainer ? createPortal(surface, portalContainer) : surface}
    </div>
  );
}
